 data=json.loads((GEN/(summary['id']+'.json')).read_text());folder=GEN/'usd'/summary['id'];folder.mkdir(parents=True,exist_ok=True);(folder/'textures').mkdir(exist_ok=True);layer=folder/'terrain.usdc';stage=Usd.Stage.CreateNew(str(layer));UsdGeom.SetStageUpAxis(stage,UsdGeom.Tokens.y);UsdGeom.SetStageMetersPerUnit(stage,1);root=UsdGeom.Xform.Define(stage,'/Terrain');stage.SetDefaultPrim(root.GetPrim())
